import * as fs from "fs";
import csv from "csv-parser";

const filePath = "./california_cities.csv";

let countySet = new Set<string>();
let count = 0;
let countyCityCountMap = new Map<string, Set<string>>();

type countyCityCount = {
  [key: string] : number;
}
// for cities
let numberBuckets = new Map<number, [string,number][]>();

fs.createReadStream(filePath)
  .pipe(csv())
  .on("data", (data: any) => {
    // data.County is the county name
    countySet.add(data.County);
    count++;


    const county = data.County;
    const city = data.Name;

    // create set if county not indexed
    if (countyCityCountMap.get(county) == undefined) {
      countyCityCountMap.set(county, new Set())
    }

    // add city to county set
    countyCityCountMap.get(county)?.add(city)
  })
  .on("end", () => {
    console.log("End of file");
    // console.log(countySet);
    // console.log("number of records")
    // console.log(count);

    let tempObject:countyCityCount = {}
    for (const county of countyCityCountMap.keys()) {
      // console.log(`county: ${county}`)
      // console.log(`city count: ${countyCityCountMap.get(county)?.size}`)

      tempObject[county] = countyCityCountMap.get(county)?.size || 0;
    }

    // console.log(tempObject);

    let tempList:[string, number][] = [];
    for (const d in tempObject) {
      tempList.push([d, tempObject[d]]);
    }

    // sorted list by city counts
    tempList.sort((a,b) => b[1]-a[1])
    // console.log(tempList)

    // go through list, and put cities in buckets
    for (const cityCount of tempList) {
      // if undefined initialize array
      if (numberBuckets.get(cityCount[1])== undefined) {
        numberBuckets.set(cityCount[1], [])
      }

      // put into bucket
      numberBuckets.get(cityCount[1])?.push(cityCount);
    }

    // in each bucket sort alphabetically
    for (const key of numberBuckets.keys()) {
      let bucket = numberBuckets.get(key);
      //  sort
      bucket?.sort((a,b) => a[0].localeCompare(b[0]))
    }

    // stitch subarrs together into res
    let res:[string,number][] = [];
    for (const key of numberBuckets.keys()) {
      let t = numberBuckets.get(key) || [];
      res.push(...t);
    }

    console.log(res);
  });


/**
 * 
 * 
 * questiosn
 * 5-7
 * 
 * print out number of records in file
 * 
 * show unique counties and number of cities in each
 * 
 * order counties by number of states
 * 
 * for counties with same # of cities, order them alphabetically within the list
 */

